import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    num = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    den = (s * s) * L.max()
    if den <= 0:
        return -1.0
    return num / den


def _ramp(N, p):
    x = (np.arange(N) + 0.5) / N
    if p == 0:
        return np.ones(N)
    return x ** p


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = 0.85 * budget_seconds

    def elapsed():
        return time.process_time() - t0

    best_h = None
    best_r = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and np.all(np.isfinite(s)) and np.all(s >= 0):
            r = _R(s)
            if r > best_r:
                best_r = r
                best_h = s.copy()

    N = 2000
    # coarse log grid
    ps = np.exp(np.linspace(np.log(0.05), np.log(5.0), 100))
    best_p = 1.0
    for p in ps:
        if elapsed() > deadline:
            break
        r = _R(_ramp(N, p))
        if r > best_r:
            best_r = r
            best_p = p
            best_h = _ramp(N, p)

    # golden-section refine around best_p
    lo = max(0.01, best_p / 2.0)
    hi = best_p * 2.0
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    c = hi - gr * (hi - lo)
    d = lo + gr * (hi - lo)
    rc = _R(_ramp(N, c))
    rd = _R(_ramp(N, d))
    if rc > best_r:
        best_r = rc; best_p = c; best_h = _ramp(N, c)
    if rd > best_r:
        best_r = rd; best_p = d; best_h = _ramp(N, d)
    while elapsed() < deadline:
        if rc > rd:
            hi = d; d = c; rd = rc
            c = hi - gr * (hi - lo)
            rc = _R(_ramp(N, c))
            if rc > best_r:
                best_r = rc; best_p = c; best_h = _ramp(N, c)
        else:
            lo = c; c = d; rc = rd
            d = lo + gr * (hi - lo)
            rd = _R(_ramp(N, d))
            if rd > best_r:
                best_r = rd; best_p = d; best_h = _ramp(N, d)

    # try higher resolutions with best_p if time remains
    for N2 in (4000, 8000):
        if elapsed() > deadline:
            break
        h = _ramp(N2, best_p)
        r = _R(h)
        if r > best_r:
            best_r = r
            best_h = h

    if best_h is None:
        return np.ones(50)
    return best_h
